export async function getEndpointParamDef(endpoint: string): Promise<Schema | null> {
	if (!endpointNames.includes(endpoint as typeof endpointNames[number])) return null;
	return await (endpointParamDefLoaders[endpoint]?.() ?? Promise.resolve(emptyParamDef));
}
